// Translations for the UI. pt-BR is the source language and the fallback for any key a
// language lacks. A value is a string with {name} placeholders, or an object of plural
// forms ({one, few, many, other}) picked with Intl.PluralRules from vars.n.
// Device and Logitech product names, CLI commands and backend ids are never translated.

const I18N = {};

// Native names for the language picker, in menu order.
const LANGUAGES = [
  ["pt-BR", "Português (Brasil)"],
  ["en", "English"],
  ["es", "Español"],
  ["fr", "Français"],
  ["de", "Deutsch"],
  ["it", "Italiano"],
  ["nl", "Nederlands"],
  ["pl", "Polski"],
  ["cs", "Čeština"],
  ["sv", "Svenska"],
  ["ru", "Русский"],
  ["uk", "Українська"],
  ["tr", "Türkçe"],
  ["id", "Bahasa Indonesia"],
  ["vi", "Tiếng Việt"],
  ["hi", "हिन्दी"],
  ["ja", "日本語"],
  ["ko", "한국어"],
  ["zh-CN", "简体中文"],
  ["zh-TW", "繁體中文"],
];

let LANG = "pt-BR";

// "de-AT" -> "de", "pt-PT" -> "pt-BR", "zh-HK" -> "zh-TW"; null when not shipped.
function matchLanguage(tag) {
  const t = String(tag || "").replace(/_/g, "-").split(".")[0];
  const exact = Object.keys(I18N).find((k) => k.toLowerCase() === t.toLowerCase());
  if (exact) return exact;
  const base = t.split("-")[0].toLowerCase();
  if (base === "pt") return "pt-BR";
  if (base === "zh") return /-(tw|hk|mo|hant)\b/i.test(t) ? "zh-TW" : "zh-CN";
  return I18N[base] ? base : null;
}

// `pref` is the saved setting: "auto" follows the system language, else English.
function resolveLanguage(pref) {
  if (pref && pref !== "auto" && matchLanguage(pref)) return matchLanguage(pref);
  return matchLanguage(navigator.language) || "en";
}

// Switches the page language and tells the backend, which words the tray menu with it.
function setLanguage(pref) {
  LANG = resolveLanguage(pref);
  document.documentElement.lang = LANG;
  window.__TAURI__.core.invoke("ui_language", { lang: LANG }).catch(() => {});
}

const hasT = (key) => key in (I18N[LANG] || {}) || key in I18N["pt-BR"];

function t(key, vars) {
  let s = I18N[LANG]?.[key] ?? I18N["pt-BR"][key] ?? key;
  if (typeof s === "object") {
    const form = new Intl.PluralRules(LANG).select(Number(vars?.n));
    s = s[form] ?? s.other;
  }
  return vars ? s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m)) : s;
}

